// Actual apartment host; uses the fresh end-to-end seed generated by verify-package-one-social.
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {mkdir,readFile} from 'node:fs/promises';
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_MODULE_PATH||'playwright-core');
const out=process.env.FT_QA_DIR||'D:/Codex/Builds/Battle/package-one';await mkdir(out+'/browser-temp',{recursive:true});process.env.TEMP=process.env.TMP=out+'/browser-temp';
const seed=JSON.parse(await readFile(out+'/package-one-seed.json','utf8'));
const browser=await chromium.launch({headless:true,executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE,args:['--autoplay-policy=no-user-gesture-required']});
const context=await browser.newContext({viewport:{width:1280,height:900}}),page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));page.setDefaultTimeout(60000);
const base=process.env.BATTLE_QA_URL||'http://127.0.0.1:4175',key='battle-life-virtual-pc-v1',win=id=>page.locator('.pc-window[data-window-id="'+id+'"]');
const desktop=()=>page.waitForFunction(()=>document.querySelector('#virtual-pc')?.dataset.pcTransition==='desktop');
const shot=async name=>page.screenshot({path:out+'/'+name+'.png'});
async function enter(){await page.goto(base+'/?rev=37');await page.locator('#loading').waitFor({state:'hidden'});await page.locator('#continue-game').click();await page.waitForFunction(()=>document.querySelector('#state').textContent.startsWith('idle'));await page.locator('#actions [data-action=computer]').click();await desktop();}
async function start(label){await page.getByRole('button',{name:'Слобода',exact:true}).click();await page.getByRole('menuitem',{name:label,exact:true}).click();}
async function community(){await start('Underweb');const a=win('underweb').getByRole('textbox',{name:'Адрес или поиск Underweb'});await a.fill('underweb://social/community/makarevich-1');await a.press('Enter');}
try{
 await page.route('**/__package-host-seed',r=>r.fulfill({contentType:'text/html',body:'<!doctype html><title>Isolated save</title>'}));await page.goto(base+'/__package-host-seed');
 await page.evaluate(seed=>{localStorage.setItem('battle-life-apartment-v3',JSON.stringify(seed.profile));localStorage.setItem('battle-life-virtual-pc-v1',JSON.stringify(seed.state));localStorage.setItem('battle-life-apartment-v3-time',JSON.stringify(seed.clock));},seed);
 await enter();
 // Phone pointer dismissal consumes only the queue item, not the separate dialog unread flag.
 const unread=await page.evaluate(key=>Object.values(JSON.parse(localStorage.getItem(key)).social.dialogs).map(d=>d.unread),key);
 for(let n=0;n<10&&await page.locator('[data-phone-notice]').isVisible();n++){await page.locator('[data-phone-notice]').hover();await page.mouse.move(700,15);}
 assert.deepEqual(await page.evaluate(key=>Object.values(JSON.parse(localStorage.getItem(key)).social.dialogs).map(d=>d.unread),key),unread);
 await community();await page.getByRole('button',{name:'Открыть общий итог',exact:true}).click();
 await page.waitForFunction(()=>document.querySelector('#virtual-pc').dataset.pcTransition==='reaction-speaking');
 await page.waitForFunction(()=>document.querySelector('.character-speech>div')?.textContent.length>6);
 await shot('package-host-reaction');
 const startClock=await page.locator('#home-time').textContent(),startSkills=await page.evaluate(()=>JSON.parse(localStorage.getItem('battle-life-apartment-v3')).skills);
 await page.waitForTimeout(800);assert.equal(await page.locator('#home-time').textContent(),startClock,'reaction cannot advance the game clock');
 await desktop();await page.waitForFunction(key=>JSON.parse(localStorage.getItem(key)).social.posts.length===1,key);
 assert.deepEqual(await page.evaluate(()=>JSON.parse(localStorage.getItem('battle-life-apartment-v3')).skills),startSkills);
 assert.equal(await page.locator('[data-result-summary]').count(),1);
 assert.equal(await page.evaluate(()=>Boolean(document.activeElement?.dataset?.resultSummary)),true,'summary focus restored after room reaction');
 await shot('package-host-return');
 const result=await page.evaluate(key=>{const s=JSON.parse(localStorage.getItem(key));return {posts:s.social.posts.length,status:s.resultReactions.items[0].status,version:s.social.posts[0].trackVersionId,original:s.battleSubmissions[0].trackVersionId,grades:JSON.stringify(s.judging)};},key);
 assert.equal(result.status,'complete');assert.equal(result.version,result.original);
 await start('Отойти от ПК');await page.waitForFunction(()=>document.querySelector('#state').textContent.startsWith('idle'));assert.equal(await page.locator('#camera-mode').textContent(),'Камера: 3D');
 await enter();await community();await page.getByRole('button',{name:'Открыть общий итог',exact:true}).click();await page.waitForTimeout(700);
 assert.equal(await page.locator('#virtual-pc').getAttribute('data-pc-transition'),'desktop','completed reaction must not replay after reload');
 assert.deepEqual(await page.evaluate(key=>{const s=JSON.parse(localStorage.getItem(key));return {posts:s.social.posts.length,grades:JSON.stringify(s.judging)};},key),{posts:1,grades:result.grades});
 assert.deepEqual(errors,[]);console.log('PASS actual host: phone dismissal / game-clock-free reaction / camera+focus return / same frozen post / reload no duplicate');
}catch(error){await shot('package-host-failure');console.log((await page.locator('body').innerText()).slice(-7000));throw error;}finally{await context.close();await browser.close();}
